def add_figma_file(workspace_id, figma_file_key, name=None, status=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0040000" if __import__("os").path.isdir("./environment_mix/0040000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _utc_day_key(dt):
        return dt.strftime("%Y-%m-%d")

    def _new_id(prefix):
        # Deterministic enough for local store; matches fig_* prefix convention loosely
        return f"{prefix}_{uuid.uuid4().hex[:12].upper()}"

    def _record_api_request(api_requests, workspace_id, tool_name, figma_file_id, request_params,
                            downstream_endpoint=None, downstream_status_code=None, status="ok",
                            error_message=None, duration_ms=None):
        ts = _now()
        row = {
            "id": _new_id("fig_req"),
            "workspace_id": workspace_id,
            "tool_name": tool_name,
            "figma_file_id": figma_file_id,
            "request_params": request_params if isinstance(request_params, dict) else {},
            "downstream_endpoint": downstream_endpoint,
            "downstream_status_code": downstream_status_code,
            "status": status,
            "error_message": error_message,
            "duration_ms": duration_ms,
            "created_at": ts,
            "updated_at": ts,
        }
        api_requests.append(row)
        return row

    start = time.time()
    tool = "add_figma_file"
    req_params = {"workspace_id": workspace_id, "figma_file_key": figma_file_key, "name": name, "status": status}

    # Validate inputs
    if not isinstance(workspace_id, str) or not re.match(r"^fig_ws_[0-9A-Z]{3,}$", workspace_id):
        api_requests = _load("api_requests.json")
        _record_api_request(api_requests, workspace_id if isinstance(workspace_id, str) else "unknown", tool, None, req_params,
                            status="error", error_message="Invalid workspace_id", duration_ms=int((time.time() - start) * 1000))
        _save("api_requests.json", api_requests)
        return _err("VALIDATION_ERROR", "Invalid workspace_id")
    if not isinstance(figma_file_key, str) or not (1 <= len(figma_file_key) <= 128):
        api_requests = _load("api_requests.json")
        _record_api_request(api_requests, workspace_id, tool, None, req_params,
                            status="error", error_message="Invalid figma_file_key", duration_ms=int((time.time() - start) * 1000))
        _save("api_requests.json", api_requests)
        return _err("VALIDATION_ERROR", "Invalid figma_file_key (length must be 1..128)")
    if name is not None and not isinstance(name, str):
        api_requests = _load("api_requests.json")
        _record_api_request(api_requests, workspace_id, tool, None, req_params,
                            status="error", error_message="Invalid name", duration_ms=int((time.time() - start) * 1000))
        _save("api_requests.json", api_requests)
        return _err("VALIDATION_ERROR", "Invalid name")
    allowed_status = {"active", "archived", "error", "deleted"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            api_requests = _load("api_requests.json")
            _record_api_request(api_requests, workspace_id, tool, None, req_params,
                                status="error", error_message="Invalid status", duration_ms=int((time.time() - start) * 1000))
            _save("api_requests.json", api_requests)
            return _err("VALIDATION_ERROR", "Invalid status")

    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)

    api_requests = _load("api_requests.json")

    if not ws:
        _record_api_request(api_requests, workspace_id, tool, None, req_params,
                            status="error", error_message="Workspace not found", duration_ms=int((time.time() - start) * 1000))
        _save("api_requests.json", api_requests)
        return _err("NOT_FOUND", "Workspace not found")

    # Mutating tool requires active workspace
    if ws.get("status") != "active":
        _record_api_request(api_requests, workspace_id, tool, None, req_params,
                            status="error", error_message="Workspace not active", duration_ms=int((time.time() - start) * 1000))
        _save("api_requests.json", api_requests)
        return _err("UNAUTHORIZED", "Workspace is not active")

    # Quota enforcement: daily requests
    now_dt = datetime.datetime.utcnow()
    day = _utc_day_key(now_dt)
    quota_requests = ws.get("quota_daily_requests")
    if not isinstance(quota_requests, int):
        quota_requests = 0
    # Count tool calls + downstream calls: approximate by counting api_requests rows for the day for this workspace
    used_requests = 0
    for r in api_requests:
        if r.get("workspace_id") != workspace_id:
            continue
        created = _parse_dt(r.get("created_at"))
        if created and _utc_day_key(created) == day:
            used_requests += 1
    if used_requests + 1 > quota_requests:
        _record_api_request(api_requests, workspace_id, tool, None, req_params,
                            status="rate_limited", error_message="Daily request quota exceeded",
                            duration_ms=int((time.time() - start) * 1000))
        _save("api_requests.json", api_requests)
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded", quota="quota_daily_requests")

    figma_files = _load("figma_files.json")

    existing = next((f for f in figma_files if f.get("workspace_id") == workspace_id and f.get("figma_file_key") == figma_file_key), None)
    ts = _now()
    if existing:
        # Upsert: do not change workspace_id; update mutable fields
        if name is not None:
            existing["name"] = name
        if status is not None:
            # validate lifecycle transition if changing
            cur = existing.get("status")
            if cur != status:
                transitions = {
                    "active": {"archived", "error", "deleted"},
                    "archived": {"active", "deleted"},
                    "error": {"active", "archived", "deleted"},
                    "deleted": set(),
                }
                if cur not in transitions or status not in transitions[cur]:
                    _record_api_request(api_requests, workspace_id, tool, existing.get("id"), req_params,
                                        status="error", error_message="Invalid status transition",
                                        duration_ms=int((time.time() - start) * 1000))
                    _save("api_requests.json", api_requests)
                    return _err("INVALID_TRANSITION", f"Cannot transition figma_files.status from '{cur}' to '{status}'")
                existing["status"] = status
        existing["updated_at"] = ts
        file_row = existing
    else:
        file_row = {
            "id": _new_id("fig_file"),
            "workspace_id": workspace_id,
            "figma_file_key": figma_file_key,
            "name": name,
            "thumbnail_url": None,
            "last_fetched_at": None,
            "comments_last_synced_at": None,
            "status": status if status is not None else "active",
            "last_error_code": None,
            "last_error_message": None,
            "created_at": ts,
            "updated_at": ts,
        }
        figma_files.append(file_row)

    _save("figma_files.json", figma_files)

    _record_api_request(api_requests, workspace_id, tool, file_row.get("id"), req_params,
                        status="ok", duration_ms=int((time.time() - start) * 1000))
    _save("api_requests.json", api_requests)

    return {"figma_file": file_row}

def view_node(workspace_id, figma_file_id, figma_node_id, use_cache=None, refresh=None, ttl_seconds=None, scale=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0040000" if __import__("os").path.isdir("./environment_mix/0040000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _utc_day_key(dt):
        return dt.strftime("%Y-%m-%d")

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:12].upper()}"

    def _record_api_request(api_requests, workspace_id, tool_name, figma_file_id, request_params,
                            downstream_endpoint=None, downstream_status_code=None, status="ok",
                            error_message=None, duration_ms=None):
        ts = _now()
        row = {
            "id": _new_id("fig_req"),
            "workspace_id": workspace_id,
            "tool_name": tool_name,
            "figma_file_id": figma_file_id,
            "request_params": request_params if isinstance(request_params, dict) else {},
            "downstream_endpoint": downstream_endpoint,
            "downstream_status_code": downstream_status_code,
            "status": status,
            "error_message": error_message,
            "duration_ms": duration_ms,
            "created_at": ts,
            "updated_at": ts,
        }
        api_requests.append(row)
        return row

    start = time.time()
    tool = "view_node"
    req_params = {
        "workspace_id": workspace_id,
        "figma_file_id": figma_file_id,
        "figma_node_id": figma_node_id,
        "use_cache": use_cache,
        "refresh": refresh,
        "ttl_seconds": ttl_seconds,
        "scale": scale,
    }

    # Defaults
    if use_cache is None:
        use_cache = True
    if refresh is None:
        refresh = False

    # Validate
    if not isinstance(workspace_id, str) or not re.match(r"^fig_ws_[0-9A-Z]{3,}$", workspace_id):
        api_requests = _load("api_requests.json")
        _record_api_request(api_requests, workspace_id if isinstance(workspace_id, str) else "unknown", tool, None, req_params,
                            status="error", error_message="Invalid workspace_id", duration_ms=int((time.time() - start) * 1000))
        _save("api_requests.json", api_requests)
        return _err("VALIDATION_ERROR", "Invalid workspace_id")
    if not isinstance(figma_file_id, str) or not re.match(r"^fig_file_[0-9A-Z]{3,}$", figma_file_id):
        api_requests = _load("api_requests.json")
        _record_api_request(api_requests, workspace_id, tool, None, req_params,
                            status="error", error_message="Invalid figma_file_id", duration_ms=int((time.time() - start) * 1000))
        _save("api_requests.json", api_requests)
        return _err("VALIDATION_ERROR", "Invalid figma_file_id")
    if not isinstance(figma_node_id, str) or len(figma_node_id) < 1:
        api_requests = _load("api_requests.json")
        _record_api_request(api_requests, workspace_id, tool, figma_file_id, req_params,
                            status="error", error_message="Invalid figma_node_id", duration_ms=int((time.time() - start) * 1000))
        _save("api_requests.json", api_requests)
        return _err("VALIDATION_ERROR", "Invalid figma_node_id")
    if not isinstance(use_cache, bool) or not isinstance(refresh, bool):
        api_requests = _load("api_requests.json")
        _record_api_request(api_requests, workspace_id, tool, figma_file_id, req_params,
                            status="error", error_message="Invalid cache flags", duration_ms=int((time.time() - start) * 1000))
        _save("api_requests.json", api_requests)
        return _err("VALIDATION_ERROR", "use_cache and refresh must be boolean")
    if refresh and use_cache:
        # "incompatible cache flags" as per tool description
        api_requests = _load("api_requests.json")
        _record_api_request(api_requests, workspace_id, tool, figma_file_id, req_params,
                            status="error", error_message="Incompatible cache flags", duration_ms=int((time.time() - start) * 1000))
        _save("api_requests.json", api_requests)
        return _err("VALIDATION_ERROR", "refresh=true is incompatible with use_cache=true (set use_cache=false when refreshing)")
    if ttl_seconds is not None:
        if not isinstance(ttl_seconds, int) or ttl_seconds < 0:
            api_requests = _load("api_requests.json")
            _record_api_request(api_requests, workspace_id, tool, figma_file_id, req_params,
                                status="error", error_message="Invalid ttl_seconds", duration_ms=int((time.time() - start) * 1000))
            _save("api_requests.json", api_requests)
            return _err("VALIDATION_ERROR", "ttl_seconds must be an integer >= 0")
        # schema constraint on stored field: 60..604800 (enforced when writing)
    if scale is not None:
        if not (isinstance(scale, int) or isinstance(scale, float)) or scale < 0.01:
            api_requests = _load("api_requests.json")
            _record_api_request(api_requests, workspace_id, tool, figma_file_id, req_params,
                                status="error", error_message="Invalid scale", duration_ms=int((time.time() - start) * 1000))
            _save("api_requests.json", api_requests)
            return _err("VALIDATION_ERROR", "scale must be a number >= 0.01")

    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)

    api_requests = _load("api_requests.json")

    if not ws:
        _record_api_request(api_requests, workspace_id, tool, figma_file_id, req_params,
                            status="error", error_message="Workspace not found", duration_ms=int((time.time() - start) * 1000))
        _save("api_requests.json", api_requests)
        return _err("NOT_FOUND", "Workspace not found")

    # Quota enforcement (reads count too)
    now_dt = datetime.datetime.utcnow()
    day = _utc_day_key(now_dt)
    quota_requests = ws.get("quota_daily_requests")
    if not isinstance(quota_requests, int):
        quota_requests = 0
    used_requests = 0
    for r in api_requests:
        if r.get("workspace_id") != workspace_id:
            continue
        created = _parse_dt(r.get("created_at"))
        if created and _utc_day_key(created) == day:
            used_requests += 1
    if used_requests + 1 > quota_requests:
        _record_api_request(api_requests, workspace_id, tool, figma_file_id, req_params,
                            status="rate_limited", error_message="Daily request quota exceeded",
                            duration_ms=int((time.time() - start) * 1000))
        _save("api_requests.json", api_requests)
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded", quota="quota_daily_requests")

    figma_files = _load("figma_files.json")
    file_row = next((f for f in figma_files if f.get("id") == figma_file_id and f.get("workspace_id") == workspace_id), None)
    if not file_row:
        _record_api_request(api_requests, workspace_id, tool, figma_file_id, req_params,
                            status="error", error_message="File not found for workspace", duration_ms=int((time.time() - start) * 1000))
        _save("api_requests.json", api_requests)
        return _err("NOT_FOUND", "Registered file not found for this workspace")

    if file_row.get("status") == "deleted":
        _record_api_request(api_requests, workspace_id, tool, figma_file_id, req_params,
                            status="error", error_message="File deleted", duration_ms=int((time.time() - start) * 1000))
        _save("api_requests.json", api_requests)
        return _err("NOT_FOUND", "Registered file is deleted")

    figma_nodes = _load("figma_nodes.json")
    node = next((n for n in figma_nodes if n.get("file_id") == figma_file_id and n.get("figma_node_id") == figma_node_id), None)

    # Check cache validity if requested and not forcing refresh
    if use_cache and not refresh and node and node.get("thumbnail_url"):
        fetched_at = _parse_dt(node.get("thumbnail_fetched_at"))
        ttl = node.get("thumbnail_ttl_seconds")
        if isinstance(ttl, int) and fetched_at:
            expires = fetched_at + datetime.timedelta(seconds=ttl)
            if expires > now_dt:
                _record_api_request(api_requests, workspace_id, tool, figma_file_id, req_params,
                                    status="ok", duration_ms=int((time.time() - start) * 1000))
                _save("api_requests.json", api_requests)
                return {
                    "figma_node": node,
                    "thumbnail_url": node.get("thumbnail_url"),
                    "cache": {"hit": True, "expires_at": expires.replace(microsecond=0).isoformat() + "Z"},
                }

    # Simulate downstream fetch (offline): generate a stable-ish URL and update cache
    # Enforce stored ttl constraint; default to existing ttl or 3600
    new_ttl = ttl_seconds if ttl_seconds is not None else (node.get("thumbnail_ttl_seconds") if node else 3600)
    if not isinstance(new_ttl, int):
        new_ttl = 3600
    if new_ttl < 60:
        new_ttl = 60
    if new_ttl > 604800:
        new_ttl = 604800

    # "Downstream call" consumes another request from quota by business rule. Enforce it.
    if used_requests + 2 > quota_requests:
        _record_api_request(api_requests, workspace_id, tool, figma_file_id, req_params,
                            status="rate_limited", error_message="Daily request quota exceeded (downstream)",
                            duration_ms=int((time.time() - start) * 1000))
        _save("api_requests.json", api_requests)
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded", quota="quota_daily_requests")

    # Create a synthetic downstream request log entry as well (counts toward quota)
    downstream_endpoint = f"/v1/images/{file_row.get('figma_file_key')}"
    _record_api_request(api_requests, workspace_id, tool, figma_file_id, req_params,
                        downstream_endpoint=downstream_endpoint, downstream_status_code=200,
                        status="ok", duration_ms=None)

    ts = _now()
    # Upsert node
    if node:
        # status transitions: stale->active allowed; active->active ok
        cur = node.get("status")
        if cur == "deleted":
            # cannot resurrect
            _record_api_request(api_requests, workspace_id, tool, figma_file_id, req_params,
                                status="error", error_message="Node is deleted", duration_ms=int((time.time() - start) * 1000))
            _save("api_requests.json", api_requests)
            return _err("INVALID_TRANSITION", "Cannot update a deleted node cache record")
        if cur == "stale":
            node["status"] = "active"
        node["thumbnail_ttl_seconds"] = new_ttl
        node["thumbnail_fetched_at"] = ts
        sc = scale if scale is not None else 1.0
        node["thumbnail_url"] = f"https://figma.invalid/thumbnails/{file_row.get('figma_file_key')}/{figma_node_id}?scale={sc}"
        node["updated_at"] = ts
    else:
        node = {
            "id": _new_id("fig_node"),
            "file_id": figma_file_id,
            "figma_node_id": figma_node_id,
            "name": None,
            "thumbnail_url": None,
            "thumbnail_fetched_at": None,
            "thumbnail_ttl_seconds": new_ttl,
            "status": "active",
            "created_at": ts,
            "updated_at": ts,
        }
        sc = scale if scale is not None else 1.0
        node["thumbnail_url"] = f"https://figma.invalid/thumbnails/{file_row.get('figma_file_key')}/{figma_node_id}?scale={sc}"
        node["thumbnail_fetched_at"] = ts
        figma_nodes.append(node)

    _save("figma_nodes.json", figma_nodes)

    _record_api_request(api_requests, workspace_id, tool, figma_file_id, req_params,
                        status="ok", duration_ms=int((time.time() - start) * 1000))
    _save("api_requests.json", api_requests)

    return {
        "figma_node": node,
        "thumbnail_url": node.get("thumbnail_url"),
        "cache": {"hit": False, "ttl_seconds": new_ttl},
    }

def read_comments(workspace_id, figma_file_id, sync=None, resolved=None, sync_status=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, re, time, uuid, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0040000" if __import__("os").path.isdir("./environment_mix/0040000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _utc_day_key(dt):
        return dt.strftime("%Y-%m-%d")

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:12].upper()}"

    def _record_api_request(api_requests, workspace_id, tool_name, figma_file_id, request_params,
                            downstream_endpoint=None, downstream_status_code=None, status="ok",
                            error_message=None, duration_ms=None):
        ts = _now()
        row = {
            "id": _new_id("fig_req"),
            "workspace_id": workspace_id,
            "tool_name": tool_name,
            "figma_file_id": figma_file_id,
            "request_params": request_params if isinstance(request_params, dict) else {},
            "downstream_endpoint": downstream_endpoint,
            "downstream_status_code": downstream_status_code,
            "status": status,
            "error_message": error_message,
            "duration_ms": duration_ms,
            "created_at": ts,
            "updated_at": ts,
        }
        api_requests.append(row)
        return row

    def _encode_cursor(offset):
        payload = json.dumps({"offset": offset}, separators=(",", ":")).encode("utf-8")
        return base64.urlsafe_b64encode(payload).decode("ascii").rstrip("=")

    def _decode_cursor(c):
        if not c:
            return 0
        if not isinstance(c, str):
            return None
        pad = "=" * (-len(c) % 4)
        try:
            raw = base64.urlsafe_b64decode((c + pad).encode("ascii"))
            obj = json.loads(raw.decode("utf-8"))
            off = obj.get("offset")
            if isinstance(off, int) and off >= 0:
                return off
            return None
        except Exception:
            return None

    start = time.time()
    tool = "read_comments"
    req_params = {
        "workspace_id": workspace_id,
        "figma_file_id": figma_file_id,
        "sync": sync,
        "resolved": resolved,
        "sync_status": sync_status,
        "limit": limit,
        "cursor": cursor,
        "sort": sort,
    }

    if sync is None:
        sync = False
    if limit is None:
        limit = 50
    if sort is None:
        sort = "figma_created_at_desc"

    # Validate
    if not isinstance(workspace_id, str) or not re.match(r"^fig_ws_[0-9A-Z]{3,}$", workspace_id):
        api_requests = _load("api_requests.json")
        _record_api_request(api_requests, workspace_id if isinstance(workspace_id, str) else "unknown", tool, None, req_params,
                            status="error", error_message="Invalid workspace_id", duration_ms=int((time.time() - start) * 1000))
        _save("api_requests.json", api_requests)
        return _err("VALIDATION_ERROR", "Invalid workspace_id")
    if not isinstance(figma_file_id, str) or not re.match(r"^fig_file_[0-9A-Z]{3,}$", figma_file_id):
        api_requests = _load("api_requests.json")
        _record_api_request(api_requests, workspace_id, tool, None, req_params,
                            status="error", error_message="Invalid figma_file_id", duration_ms=int((time.time() - start) * 1000))
        _save("api_requests.json", api_requests)
        return _err("VALIDATION_ERROR", "Invalid figma_file_id")
    if not isinstance(sync, bool):
        api_requests = _load("api_requests.json")
        _record_api_request(api_requests, workspace_id, tool, figma_file_id, req_params,
                            status="error", error_message="Invalid sync", duration_ms=int((time.time() - start) * 1000))
        _save("api_requests.json", api_requests)
        return _err("VALIDATION_ERROR", "sync must be boolean")
    if resolved is not None and not isinstance(resolved, bool):
        api_requests = _load("api_requests.json")
        _record_api_request(api_requests, workspace_id, tool, figma_file_id, req_params,
                            status="error", error_message="Invalid resolved", duration_ms=int((time.time() - start) * 1000))
        _save("api_requests.json", api_requests)
        return _err("VALIDATION_ERROR", "resolved must be boolean")
    allowed_sync_status = {"synced", "pending_post", "post_failed", "tombstoned"}
    if sync_status is not None and (not isinstance(sync_status, str) or sync_status not in allowed_sync_status):
        api_requests = _load("api_requests.json")
        _record_api_request(api_requests, workspace_id, tool, figma_file_id, req_params,
                            status="error", error_message="Invalid sync_status", duration_ms=int((time.time() - start) * 1000))
        _save("api_requests.json", api_requests)
        return _err("VALIDATION_ERROR", "Invalid sync_status")
    if not isinstance(limit, int) or limit < 1:
        api_requests = _load("api_requests.json")
        _record_api_request(api_requests, workspace_id, tool, figma_file_id, req_params,
                            status="error", error_message="Invalid limit", duration_ms=int((time.time() - start) * 1000))
        _save("api_requests.json", api_requests)
        return _err("VALIDATION_ERROR", "limit must be an integer >= 1")
    allowed_sort = {"figma_created_at_asc", "figma_created_at_desc", "created_at_asc", "created_at_desc"}
    if not isinstance(sort, str) or sort not in allowed_sort:
        api_requests = _load("api_requests.json")
        _record_api_request(api_requests, workspace_id, tool, figma_file_id, req_params,
                            status="error", error_message="Invalid sort", duration_ms=int((time.time() - start) * 1000))
        _save("api_requests.json", api_requests)
        return _err("VALIDATION_ERROR", "Invalid sort")

    offset = _decode_cursor(cursor)
    if offset is None:
        api_requests = _load("api_requests.json")
        _record_api_request(api_requests, workspace_id, tool, figma_file_id, req_params,
                            status="error", error_message="Malformed cursor", duration_ms=int((time.time() - start) * 1000))
        _save("api_requests.json", api_requests)
        return _err("VALIDATION_ERROR", "Malformed cursor")

    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    api_requests = _load("api_requests.json")

    if not ws:
        _record_api_request(api_requests, workspace_id, tool, figma_file_id, req_params,
                            status="error", error_message="Workspace not found", duration_ms=int((time.time() - start) * 1000))
        _save("api_requests.json", api_requests)
        return _err("NOT_FOUND", "Workspace not found")

    # Quota enforcement (reads included)
    now_dt = datetime.datetime.utcnow()
    day = _utc_day_key(now_dt)
    quota_requests = ws.get("quota_daily_requests")
    if not isinstance(quota_requests, int):
        quota_requests = 0
    used_requests = 0
    for r in api_requests:
        if r.get("workspace_id") != workspace_id:
            continue
        created = _parse_dt(r.get("created_at"))
        if created and _utc_day_key(created) == day:
            used_requests += 1
    if used_requests + 1 > quota_requests:
        _record_api_request(api_requests, workspace_id, tool, figma_file_id, req_params,
                            status="rate_limited", error_message="Daily request quota exceeded",
                            duration_ms=int((time.time() - start) * 1000))
        _save("api_requests.json", api_requests)
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded", quota="quota_daily_requests")

    figma_files = _load("figma_files.json")
    file_row = next((f for f in figma_files if f.get("id") == figma_file_id and f.get("workspace_id") == workspace_id), None)
    if not file_row:
        _record_api_request(api_requests, workspace_id, tool, figma_file_id, req_params,
                            status="error", error_message="File not found for workspace", duration_ms=int((time.time() - start) * 1000))
        _save("api_requests.json", api_requests)
        return _err("NOT_FOUND", "Registered file not found for this workspace")

    if file_row.get("status") == "deleted":
        _record_api_request(api_requests, workspace_id, tool, figma_file_id, req_params,
                            status="error", error_message="File deleted", duration_ms=int((time.time() - start) * 1000))
        _save("api_requests.json", api_requests)
        return _err("NOT_FOUND", "Registered file is deleted")

    # Optional sync behavior: if comments_last_synced_at is stale or sync==True, perform a "downstream" sync
    # We'll treat "recent" as within 5 minutes.
    do_sync = bool(sync)
    last_synced = _parse_dt(file_row.get("comments_last_synced_at"))
    if not do_sync:
        if not last_synced:
            do_sync = True
        else:
            if (now_dt - last_synced) > datetime.timedelta(minutes=5):
                do_sync = True

    if do_sync:
        # Downstream sync consumes another quota unit.
        if used_requests + 2 > quota_requests:
            _record_api_request(api_requests, workspace_id, tool, figma_file_id, req_params,
                                status="rate_limited", error_message="Daily request quota exceeded (downstream)",
                                duration_ms=int((time.time() - start) * 1000))
            _save("api_requests.json", api_requests)
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded", quota="quota_daily_requests")

        downstream_endpoint = f"/v1/files/{file_row.get('figma_file_key')}/comments"
        _record_api_request(api_requests, workspace_id, tool, figma_file_id, req_params,
                            downstream_endpoint=downstream_endpoint, downstream_status_code=200, status="ok")

        # Offline "sync": no new remote data available; mark comments_last_synced_at as now to reflect the sync attempt.
        file_row["comments_last_synced_at"] = _now()
        file_row["updated_at"] = _now()
        _save("figma_files.json", figma_files)

    figma_comments = _load("figma_comments.json")

    rows = [c for c in figma_comments if c.get("file_id") == figma_file_id]

    if resolved is not None:
        rows = [c for c in rows if bool(c.get("resolved")) == resolved]
    if sync_status is not None:
        rows = [c for c in rows if c.get("sync_status") == sync_status]

    # Sort
    def _key(c):
        if sort.startswith("figma_created_at"):
            dt = _parse_dt(c.get("figma_created_at")) or _parse_dt(c.get("created_at")) or datetime.datetime(1970, 1, 1)
        else:
            dt = _parse_dt(c.get("created_at")) or datetime.datetime(1970, 1, 1)
        return dt

    reverse = sort.endswith("_desc")
    rows.sort(key=_key, reverse=reverse)

    total = len(rows)
    page = rows[offset: offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = _encode_cursor(next_off) if has_more else None

    _record_api_request(api_requests, workspace_id, tool, figma_file_id, req_params,
                        status="ok", duration_ms=int((time.time() - start) * 1000))
    _save("api_requests.json", api_requests)

    return {
        "comments": page,
        "pagination": {"total": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor},
        "synced": bool(do_sync),
    }

def list_figma_files(workspace_id, status=None, figma_file_key=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0040000" if __import__("os").path.isdir("./environment_mix/0040000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _rid(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:20].upper()}"

    def _record_request(workspace_id_val, status_val, figma_file_id_val=None, error_message=None, duration_ms=None, request_params=None):
        reqs = _load("api_requests.json")
        row = {
            "id": _rid("fig_req"),
            "workspace_id": workspace_id_val,
            "tool_name": "list_figma_files",  # not in schema enum; store anyway for observability
            "figma_file_id": figma_file_id_val,
            "request_params": request_params if isinstance(request_params, dict) else {},
            "downstream_endpoint": None,
            "downstream_status_code": None,
            "status": status_val,
            "error_message": error_message,
            "duration_ms": duration_ms,
            "created_at": now,
            "updated_at": now,
        }
        reqs.append(row)
        _save("api_requests.json", reqs)
        return row

    def _finalize(req_row_id, status_val, error_message=None, duration_ms=None):
        reqs = _load("api_requests.json")
        for r in reqs:
            if r.get("id") == req_row_id:
                r["status"] = status_val
                r["error_message"] = error_message
                r["duration_ms"] = duration_ms
                r["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                _save("api_requests.json", reqs)
                return True
        return False

    def _utc_day(ts_iso):
        if isinstance(ts_iso, str) and len(ts_iso) >= 10:
            return ts_iso[:10]
        return datetime.datetime.utcnow().date().isoformat()

    def _check_quota(workspace_row):
        reqs = _load("api_requests.json")
        today = datetime.datetime.utcnow().date().isoformat()
        wsid = workspace_row["id"]
        daily_total = 0
        for r in reqs:
            if r.get("workspace_id") == wsid and _utc_day(r.get("created_at")) == today:
                daily_total += 1
        quota_req = workspace_row.get("quota_daily_requests")
        if not isinstance(quota_req, int) or quota_req < 0:
            quota_req = 0
        if daily_total + 1 > quota_req:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", quota="quota_daily_requests", limit=quota_req, used=daily_total)
        return None

    # Validate
    if not isinstance(workspace_id, str) or not re.match(r"^fig_ws_[0-9A-Z]{3,}$", workspace_id or ""):
        req = _record_request(workspace_id if isinstance(workspace_id, str) else "unknown", "error",
                              error_message="Invalid workspace_id.",
                              request_params={"workspace_id": workspace_id, "status": status, "figma_file_key": figma_file_key, "limit": limit, "cursor": cursor, "sort": sort})
        _finalize(req["id"], "error", "Invalid workspace_id.", int((time.time() - start) * 1000))
        return _err("VALIDATION_ERROR", "Invalid workspace_id.", field="workspace_id")

    allowed_status = {None, "active", "archived", "error", "deleted"}
    if status not in allowed_status:
        req = _record_request(workspace_id, "error", error_message="Invalid status filter.",
                              request_params={"workspace_id": workspace_id, "status": status, "figma_file_key": figma_file_key, "limit": limit, "cursor": cursor, "sort": sort})
        _finalize(req["id"], "error", "Invalid status filter.", int((time.time() - start) * 1000))
        return _err("VALIDATION_ERROR", "Invalid status filter.", field="status")

    if figma_file_key is not None and (not isinstance(figma_file_key, str) or len(figma_file_key) < 1 or len(figma_file_key) > 128):
        req = _record_request(workspace_id, "error", error_message="Invalid figma_file_key.",
                              request_params={"workspace_id": workspace_id, "status": status, "figma_file_key": figma_file_key, "limit": limit, "cursor": cursor, "sort": sort})
        _finalize(req["id"], "error", "Invalid figma_file_key.", int((time.time() - start) * 1000))
        return _err("VALIDATION_ERROR", "Invalid figma_file_key.", field="figma_file_key")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        req = _record_request(workspace_id, "error", error_message="Invalid limit.",
                              request_params={"workspace_id": workspace_id, "status": status, "figma_file_key": figma_file_key, "limit": limit, "cursor": cursor, "sort": sort})
        _finalize(req["id"], "error", "Invalid limit.", int((time.time() - start) * 1000))
        return _err("VALIDATION_ERROR", "Invalid limit; must be between 1 and 200.", field="limit")

    allowed_sort = {None, "created_at_asc", "created_at_desc", "updated_at_asc", "updated_at_desc", "name_asc", "name_desc"}
    if sort not in allowed_sort:
        req = _record_request(workspace_id, "error", error_message="Invalid sort.",
                              request_params={"workspace_id": workspace_id, "status": status, "figma_file_key": figma_file_key, "limit": limit, "cursor": cursor, "sort": sort})
        _finalize(req["id"], "error", "Invalid sort.", int((time.time() - start) * 1000))
        return _err("VALIDATION_ERROR", "Invalid sort.", field="sort")

    if cursor is not None and (not isinstance(cursor, str) or len(cursor) > 2000):
        req = _record_request(workspace_id, "error", error_message="Invalid cursor.",
                              request_params={"workspace_id": workspace_id, "status": status, "figma_file_key": figma_file_key, "limit": limit, "cursor": cursor, "sort": sort})
        _finalize(req["id"], "error", "Invalid cursor.", int((time.time() - start) * 1000))
        return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    # Resolve workspace
    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        req = _record_request(workspace_id, "error", error_message="Workspace not found.",
                              request_params={"workspace_id": workspace_id, "status": status, "figma_file_key": figma_file_key, "limit": limit, "cursor": cursor, "sort": sort})
        _finalize(req["id"], "error", "Workspace not found.", int((time.time() - start) * 1000))
        return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)

    # Quota check + request record
    qerr = _check_quota(ws)
    if qerr:
        req = _record_request(workspace_id, "rate_limited", error_message=qerr["error"]["message"],
                              request_params={"workspace_id": workspace_id, "status": status, "figma_file_key": figma_file_key, "limit": limit, "cursor": cursor, "sort": sort})
        _finalize(req["id"], "rate_limited", qerr["error"]["message"], int((time.time() - start) * 1000))
        return qerr

    req = _record_request(workspace_id, "error",
                          request_params={"workspace_id": workspace_id, "status": status, "figma_file_key": figma_file_key, "limit": limit, "cursor": cursor, "sort": sort})

    # Filter
    files = _load("figma_files.json")
    rows = [r for r in files if r.get("workspace_id") == workspace_id]
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]
    if figma_file_key is not None:
        rows = [r for r in rows if r.get("figma_file_key") == figma_file_key]

    # Sort
    def _k_ts(v):
        return v or ""
    def _k_name(v):
        if v is None:
            return ""
        return str(v).lower()

    if sort is None:
        sort = "updated_at_desc"

    reverse = sort.endswith("_desc")
    if sort.startswith("created_at_"):
        rows.sort(key=lambda r: _k_ts(r.get("created_at")), reverse=reverse)
    elif sort.startswith("updated_at_"):
        rows.sort(key=lambda r: _k_ts(r.get("updated_at")), reverse=reverse)
    elif sort.startswith("name_"):
        rows.sort(key=lambda r: _k_name(r.get("name")), reverse=reverse)

    total = len(rows)

    # Pagination (cursor is base10 offset)
    offset = 0
    if cursor:
        try:
            offset = int(cursor)
            if offset < 0:
                raise ValueError()
        except ValueError:
            _finalize(req["id"], "error", "Invalid cursor.", int((time.time() - start) * 1000))
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    page = rows[offset:offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = str(next_offset) if has_more else None

    dur = int((time.time() - start) * 1000)
    _finalize(req["id"], "ok", None, dur)

    return {
        "data": page,
        "pagination": {
            "total": total,
            "limit": limit,
            "cursor": str(offset),
            "has_more": has_more,
            "next_cursor": next_cursor,
            "sort": sort,
        },
        "request": {"id": req["id"], "status": "ok", "duration_ms": dur},
    }

def get_figma_file(workspace_id, figma_file_id=None, figma_file_key=None, **_extra):
    import json, os, datetime, time, re, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0040000" if __import__("os").path.isdir("./environment_mix/0040000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now_dt.isoformat() + "Z"

    def _rid(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:20].upper()}"

    # Validate inputs
    if not isinstance(workspace_id, str) or not re.match(r"^fig_ws_[0-9A-Z]{3,}$", workspace_id or ""):
        return _err("VALIDATION_ERROR", "Invalid workspace_id.")

    if figma_file_id is not None and (not isinstance(figma_file_id, str) or not re.match(r"^fig_file_[0-9A-Z]{3,}$", figma_file_id or "")):
        return _err("VALIDATION_ERROR", "Invalid figma_file_id.")
    if figma_file_key is not None and (not isinstance(figma_file_key, str) or len(figma_file_key.strip()) == 0 or len(figma_file_key) > 128):
        return _err("VALIDATION_ERROR", "Invalid figma_file_key. Must be a non-empty string up to 128 chars.")

    # Real-world relaxation: if both are provided, accept and prefer figma_file_id (do not error).
    if figma_file_id is None and figma_file_key is None:
        return _err("VALIDATION_ERROR", "Provide at least one of figma_file_id or figma_file_key.", fields=["figma_file_id", "figma_file_key"])

    workspaces = _load("workspaces.json")
    files = _load("figma_files.json")
    api_requests = _load("api_requests.json")

    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    # Tool description mentions FORBIDDEN; contract restricts codes -> UNAUTHORIZED
    if not ws:
        # Record request (best-effort) under provided workspace_id even if missing
        req = {
            "id": _rid("fig_req"),
            "workspace_id": workspace_id,
            "tool_name": "get_figma_file",
            "figma_file_id": None,
            "request_params": {"workspace_id": workspace_id, "figma_file_id": figma_file_id, "figma_file_key": figma_file_key},
            "downstream_endpoint": None,
            "downstream_status_code": None,
            "status": "error",
            "error_message": "Workspace not found.",
            "duration_ms": int((time.time() - start) * 1000),
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        api_requests.append(req)
        _save("api_requests.json", api_requests)
        return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)

    # Quota: per workspace per UTC day, count of api_requests rows (tool calls + downstream calls) <= quota_daily_requests
    def _day(iso):
        return iso[:10] if isinstance(iso, str) and len(iso) >= 10 else now_dt.date().isoformat()

    today = now_dt.date().isoformat()
    daily_count = sum(1 for r in api_requests if r.get("workspace_id") == workspace_id and _day(r.get("created_at")) == today)
    if isinstance(ws.get("quota_daily_requests"), int) and daily_count >= ws.get("quota_daily_requests", 0):
        req = {
            "id": _rid("fig_req"),
            "workspace_id": workspace_id,
            "tool_name": "get_figma_file",
            "figma_file_id": None,
            "request_params": {"workspace_id": workspace_id, "figma_file_id": figma_file_id, "figma_file_key": figma_file_key},
            "downstream_endpoint": None,
            "downstream_status_code": None,
            "status": "rate_limited",
            "error_message": "quota_daily_requests exceeded for workspace (per UTC day).",
            "duration_ms": int((time.time() - start) * 1000),
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        api_requests.append(req)
        _save("api_requests.json", api_requests)
        return _err("QUOTA_EXCEEDED", "quota_daily_requests exceeded for workspace (per UTC day).", workspace_id=workspace_id)

    # Create request log row early
    req_id = _rid("fig_req")
    req_row = {
        "id": req_id,
        "workspace_id": workspace_id,
        "tool_name": "get_figma_file",
        "figma_file_id": figma_file_id if isinstance(figma_file_id, str) else None,
        "request_params": {"workspace_id": workspace_id, "figma_file_id": figma_file_id, "figma_file_key": figma_file_key},
        "downstream_endpoint": None,
        "downstream_status_code": None,
        "status": "ok",  # may change
        "error_message": None,
        "duration_ms": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }
    api_requests.append(req_row)
    _save("api_requests.json", api_requests)

    # Resolve file within workspace
    match = None
    if figma_file_id is not None:
        fr = next((f for f in files if f.get("id") == figma_file_id), None)
        if fr and fr.get("workspace_id") == workspace_id:
            match = fr
        else:
            # If id doesn't match in workspace but key is provided, fall back to key.
            if figma_file_key is not None:
                match = next((f for f in files if f.get("workspace_id") == workspace_id and f.get("figma_file_key") == figma_file_key), None)
    else:
        match = next((f for f in files if f.get("workspace_id") == workspace_id and f.get("figma_file_key") == figma_file_key), None)

    api_requests = _load("api_requests.json")
    for r in api_requests:
        if r.get("id") == req_id:
            r["duration_ms"] = int((time.time() - start) * 1000)
            r["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
            if not match:
                r["status"] = "error"
                r["error_message"] = "File not found in workspace."
            _save("api_requests.json", api_requests)
            break

    if not match:
        return _err("NOT_FOUND", "Figma file not found in workspace.", workspace_id=workspace_id, figma_file_id=figma_file_id, figma_file_key=figma_file_key)

    return {
        "data": match,
        "meta": {
            "workspace_id": workspace_id
        }
    }

def update_figma_file(workspace_id, figma_file_id, name=None, status=None, last_error_code=None, last_error_message=None, **_extra):
    import json, os, datetime, re, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0040000" if __import__("os").path.isdir("./environment_mix/0040000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _rid(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:20].upper()}"

    def _record_request(workspace_id_val, status_val, figma_file_id_val=None, error_message=None, duration_ms=None, request_params=None):
        reqs = _load("api_requests.json")
        row = {
            "id": _rid("fig_req"),
            "workspace_id": workspace_id_val,
            "tool_name": "update_figma_file",  # not in schema enum; store anyway
            "figma_file_id": figma_file_id_val,
            "request_params": request_params if isinstance(request_params, dict) else {},
            "downstream_endpoint": None,
            "downstream_status_code": None,
            "status": status_val,
            "error_message": error_message,
            "duration_ms": duration_ms,
            "created_at": now,
            "updated_at": now,
        }
        reqs.append(row)
        _save("api_requests.json", reqs)
        return row

    def _finalize(req_row_id, status_val, error_message=None, duration_ms=None):
        reqs = _load("api_requests.json")
        for r in reqs:
            if r.get("id") == req_row_id:
                r["status"] = status_val
                r["error_message"] = error_message
                r["duration_ms"] = duration_ms
                r["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
                _save("api_requests.json", reqs)
                return True
        return False

    def _utc_day(ts_iso):
        if isinstance(ts_iso, str) and len(ts_iso) >= 10:
            return ts_iso[:10]
        return datetime.datetime.utcnow().date().isoformat()

    def _check_quota(workspace_row):
        reqs = _load("api_requests.json")
        today = datetime.datetime.utcnow().date().isoformat()
        wsid = workspace_row["id"]
        daily_total = 0
        for r in reqs:
            if r.get("workspace_id") == wsid and _utc_day(r.get("created_at")) == today:
                daily_total += 1
        quota_req = workspace_row.get("quota_daily_requests")
        if not isinstance(quota_req, int) or quota_req < 0:
            quota_req = 0
        if daily_total + 1 > quota_req:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", quota="quota_daily_requests", limit=quota_req, used=daily_total)
        return None

    # Validate required
    if not isinstance(workspace_id, str) or not re.match(r"^fig_ws_[0-9A-Z]{3,}$", workspace_id or ""):
        req = _record_request(workspace_id if isinstance(workspace_id, str) else "unknown", "error",
                              error_message="Invalid workspace_id.",
                              request_params={"workspace_id": workspace_id, "figma_file_id": figma_file_id, "name": name, "status": status, "last_error_code": last_error_code, "last_error_message": last_error_message})
        _finalize(req["id"], "error", "Invalid workspace_id.", int((time.time() - start) * 1000))
        return _err("VALIDATION_ERROR", "Invalid workspace_id.", field="workspace_id")
    if not isinstance(figma_file_id, str) or not re.match(r"^fig_file_[0-9A-Z]{3,}$", figma_file_id or ""):
        req = _record_request(workspace_id, "error", error_message="Invalid figma_file_id.",
                              request_params={"workspace_id": workspace_id, "figma_file_id": figma_file_id, "name": name, "status": status, "last_error_code": last_error_code, "last_error_message": last_error_message})
        _finalize(req["id"], "error", "Invalid figma_file_id.", int((time.time() - start) * 1000))
        return _err("VALIDATION_ERROR", "Invalid figma_file_id.", field="figma_file_id")

    if name is not None and not isinstance(name, str):
        req = _record_request(workspace_id, "error", figma_file_id, error_message="Invalid name.",
                              request_params={"workspace_id": workspace_id, "figma_file_id": figma_file_id, "name": name, "status": status, "last_error_code": last_error_code, "last_error_message": last_error_message})
        _finalize(req["id"], "error", "Invalid name.", int((time.time() - start) * 1000))
        return _err("VALIDATION_ERROR", "Invalid name.", field="name")

    allowed_status = {None, "active", "archived", "error", "deleted"}
    if status not in allowed_status:
        req = _record_request(workspace_id, "error", figma_file_id, error_message="Invalid status.",
                              request_params={"workspace_id": workspace_id, "figma_file_id": figma_file_id, "name": name, "status": status, "last_error_code": last_error_code, "last_error_message": last_error_message})
        _finalize(req["id"], "error", "Invalid status.", int((time.time() - start) * 1000))
        return _err("VALIDATION_ERROR", "Invalid status.", field="status")

    if last_error_code is not None and not isinstance(last_error_code, str):
        req = _record_request(workspace_id, "error", figma_file_id, error_message="Invalid last_error_code.",
                              request_params={"workspace_id": workspace_id, "figma_file_id": figma_file_id, "name": name, "status": status, "last_error_code": last_error_code, "last_error_message": last_error_message})
        _finalize(req["id"], "error", "Invalid last_error_code.", int((time.time() - start) * 1000))
        return _err("VALIDATION_ERROR", "Invalid last_error_code.", field="last_error_code")

    if last_error_message is not None and not isinstance(last_error_message, str):
        req = _record_request(workspace_id, "error", figma_file_id, error_message="Invalid last_error_message.",
                              request_params={"workspace_id": workspace_id, "figma_file_id": figma_file_id, "name": name, "status": status, "last_error_code": last_error_code, "last_error_message": last_error_message})
        _finalize(req["id"], "error", "Invalid last_error_message.", int((time.time() - start) * 1000))
        return _err("VALIDATION_ERROR", "Invalid last_error_message.", field="last_error_message")

    # Resolve workspace
    workspaces = _load("workspaces.json")
    ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
    if not ws:
        req = _record_request(workspace_id, "error", figma_file_id, error_message="Workspace not found.",
                              request_params={"workspace_id": workspace_id, "figma_file_id": figma_file_id, "name": name, "status": status, "last_error_code": last_error_code, "last_error_message": last_error_message})
        _finalize(req["id"], "error", "Workspace not found.", int((time.time() - start) * 1000))
        return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)

    # Mutating tool requires active workspace
    if ws.get("status") != "active":
        req = _record_request(workspace_id, "error", figma_file_id, error_message="Workspace not active.",
                              request_params={"workspace_id": workspace_id, "figma_file_id": figma_file_id, "name": name, "status": status, "last_error_code": last_error_code, "last_error_message": last_error_message})
        _finalize(req["id"], "error", "Workspace not active.", int((time.time() - start) * 1000))
        return _err("UNAUTHORIZED", "Workspace is not active; mutation not allowed.", workspace_status=ws.get("status"))

    qerr = _check_quota(ws)
    if qerr:
        req = _record_request(workspace_id, "rate_limited", figma_file_id, error_message=qerr["error"]["message"],
                              request_params={"workspace_id": workspace_id, "figma_file_id": figma_file_id, "name": name, "status": status, "last_error_code": last_error_code, "last_error_message": last_error_message})
        _finalize(req["id"], "rate_limited", qerr["error"]["message"], int((time.time() - start) * 1000))
        return qerr

    req = _record_request(workspace_id, "error", figma_file_id,
                          request_params={"workspace_id": workspace_id, "figma_file_id": figma_file_id, "name": name, "status": status, "last_error_code": last_error_code, "last_error_message": last_error_message})

    # Find file in workspace
    files = _load("figma_files.json")
    idx = None
    for i, r in enumerate(files):
        if r.get("id") == figma_file_id and r.get("workspace_id") == workspace_id:
            idx = i
            break
    if idx is None:
        dur = int((time.time() - start) * 1000)
        _finalize(req["id"], "error", "File not found in workspace.", dur)
        return _err("NOT_FOUND", "Figma file not found in workspace.", workspace_id=workspace_id, figma_file_id=figma_file_id)

    row = files[idx]
    changed = False

    # Update name
    if name is not None and name != row.get("name"):
        row["name"] = name
        changed = True

    # Status transition (enforce lifecycle transitions)
    if status is not None and status != row.get("status"):
        transitions = {
            "active": ["archived", "error", "deleted"],
            "archived": ["active", "deleted"],
            "error": ["active", "archived", "deleted"],
            "deleted": []
        }
        cur = row.get("status")
        if cur not in transitions:
            dur = int((time.time() - start) * 1000)
            _finalize(req["id"], "error", "Invalid current status.", dur)
            return _err("VALIDATION_ERROR", "Invalid current status on file.", current_status=cur)
        if status not in transitions[cur]:
            dur = int((time.time() - start) * 1000)
            _finalize(req["id"], "error", "Illegal status transition.", dur)
            return _err("INVALID_TRANSITION", "Illegal status transition.", from_status=cur, to_status=status)
        row["status"] = status
        changed = True

        # If status is error, record last_error fields; otherwise ignore & optionally clear
        if status == "error":
            if last_error_code is not None:
                row["last_error_code"] = last_error_code
            if last_error_message is not None:
                row["last_error_message"] = last_error_message
        else:
            # ignore provided error fields
            pass

    # If status not being set to error, ignore last_error_ fields per rule (no mutation)
    if not changed:
        dur = int((time.time() - start) * 1000)
        _finalize(req["id"], "error", "No fields changed.", dur)
        return _err("CONFLICT", "No changes to apply.")

    row["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    files[idx] = row
    _save("figma_files.json", files)

    # FK integrity on delete cascade for hard delete of row is not part of this tool; status=deleted is soft.

    dur = int((time.time() - start) * 1000)
    _finalize(req["id"], "ok", None, dur)
    return {"data": row, "request": {"id": req["id"], "status": "ok", "duration_ms": dur}}

def get_whoami(workspace_id=None, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0040000" if __import__("os").path.isdir("./environment_mix/0040000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"
    day_key = now.strftime("%Y-%m-%d")

    if workspace_id is not None:
        if not isinstance(workspace_id, str) or not re.match(r"^fig_ws_[0-9A-Z]{3,}$", workspace_id or ""):
            return _err("VALIDATION_ERROR", "Invalid workspace_id.")

    workspaces = _load("workspaces.json")
    api_requests = _load("api_requests.json")

    # Ambient auth: if there are no workspaces at all, nobody can be "authenticated"
    if not workspaces:
        return _err("UNAUTHORIZED", "No valid credentials/workspace context available.")

    ws = None
    if workspace_id is not None:
        ws = next((w for w in workspaces if w.get("id") == workspace_id), None)
        if not ws:
            return _err("NOT_FOUND", "Workspace not found.", workspace_id=workspace_id)

    # Record request (reads included)
    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex[:12].upper()}"
    req_row = {
        "id": _new_id("fig_req"),
        "workspace_id": (ws.get("id") if ws else workspaces[0].get("id")),
        "tool_name": "get_whoami",
        "figma_file_id": None,
        "request_params": {"workspace_id": workspace_id} if workspace_id is not None else {},
        "downstream_endpoint": None,
        "downstream_status_code": None,
        "status": "ok",
        "error_message": None,
        "duration_ms": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }
    api_requests.append(req_row)

    # If workspace provided, enforce quota_daily_requests visibility by existence; no extra auth model in schema, so allow.
    quota = None
    usage = None
    if ws:
        todays = [r for r in api_requests if r.get("workspace_id") == ws.get("id") and isinstance(r.get("created_at"), str) and r.get("created_at")[:10] == day_key]
        daily_requests_used = len(todays)
        quota_req = ws.get("quota_daily_requests") if isinstance(ws.get("quota_daily_requests"), int) else 0

        daily_comment_posts_used = 0
        for r in todays:
            if r.get("tool_name") in ("post_comment", "reply_to_comment", "retry_comment_post") and r.get("status") == "ok":
                daily_comment_posts_used += 1
        quota_posts = ws.get("quota_daily_comment_posts") if isinstance(ws.get("quota_daily_comment_posts"), int) else 0

        quota = {
            "quota_daily_requests": quota_req,
            "quota_daily_comment_posts": quota_posts
        }
        usage = {
            "utc_day": day_key,
            "daily_requests_used": daily_requests_used,
            "daily_requests_remaining": max(0, quota_req - daily_requests_used),
            "daily_comment_posts_used": daily_comment_posts_used,
            "daily_comment_posts_remaining": max(0, quota_posts - daily_comment_posts_used)
        }

    req_row["duration_ms"] = int((time.time() - start) * 1000)
    req_row["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    _save("api_requests.json", api_requests)

    identity = {
        "auth_type": "ambient_workspace_context",
        "workspace_id": (ws.get("id") if ws else None),
        "workspace_name": (ws.get("name") if ws else None),
        "workspace_status": (ws.get("status") if ws else None),
        "has_figma_token_configured": (bool(ws.get("figma_access_token_ciphertext")) if ws else None),
        "scopes": [
            "figma:file:read",
            "figma:comments:read",
            "figma:comments:write"
        ]
    }

    out = {"identity": identity}
    if ws:
        out["quota"] = quota
        out["usage"] = usage
    return out
